import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFredoka = makeLoadFont('Fredoka');

// Load playful Google Font at module level for guaranteed zero-flicker on Lambda
const { fontFamily: fredokaFamily } = loadFredoka();

// ==========================================
// SCHEMA DEFINITION & CUSTOMIZATION
// ==========================================


export type PlayingCardAnimationProps = Record<string, any>;

// ==========================================
// SUB-COMPONENTS & UTILITIES
// ==========================================

